package com.tencent.weknora.knowledge;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.tencent.weknora.model.client.*;
import com.tencent.weknora.task.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Native kb:profile; no document counter or document parse-span ownership. */
public final class KnowledgeBaseProfileHandler implements TaskHandler {
  public interface Models {ChatModel chat(long owner,String id);}
  private final KnowledgeBaseProfileRepository repository;private final ObjectMapper json;private final Models models;private final KnowledgeBaseProfileText text;private final TaskRepository tasks;private final Clock clock;
  public KnowledgeBaseProfileHandler(KnowledgeBaseProfileRepository repository,ObjectMapper json,Models models,KnowledgeBaseProfileText text,TaskRepository tasks,Clock clock){this.repository=repository;this.json=json;this.models=models;this.text=text;this.tasks=tasks;this.clock=clock;}
  private String defaultLanguage=defaultLanguage();
  private static String defaultLanguage(){String configured=KnowledgeUploadForms.goTrim(Objects.toString(System.getenv("WEKNORA_LANGUAGE"),""));return configured.isEmpty()?"zh-CN":configured;}
  public KnowledgeBaseProfileHandler withLanguage(KnowledgeProcessingLanguage language){defaultLanguage=language.resolve("");return this;}
  public String type(){return "kb:profile";}public Duration timeout(){return Duration.ofMinutes(5);}
  public static boolean eligible(JsonNode base){return base!=null&&!base.path("id").asText().isEmpty()&&base.path("type").asText().equals("document")&&!base.path("is_temporary").asBoolean();}
  public boolean enqueue(long owner,JsonNode base,boolean force,JsonNode source){if(tasks==null||!eligible(base)||base.path("tenant_id").asLong()!=owner||(!force&&!base.path("profile_config").path("enabled").asBoolean()))return false;var payload=json.createObjectNode().put("tenant_id",owner).put("knowledge_base_id",base.path("id").asText()).put("language",source.path("language").asText());if(payload.path("language").asText().isEmpty())payload.put("language",defaultLanguage);if(force)payload.put("force",true);for(String k:List.of("lf_trace_id","lf_parent_obs_id","lf_traceparent","lf_user_id","lf_session_id"))if(!source.path(k).asText().isEmpty())payload.set(k,source.get(k));try{tasks.enqueue(owner,type(),force?null:"kb-profile:"+base.path("id").asText()+":"+(clock.instant().getEpochSecond()/30),payload,3,force?Duration.ZERO:Duration.ofSeconds(30),"summary",timeout());return true;}catch(RuntimeException e){return false;}}
  public JsonNode execute(TaskRecord job,TaskCancellation cancellation)throws Exception{var payload=job.payload();if(!payload.isNull()&&!payload.isObject())throw new TaskFailure("unmarshal knowledge base profile payload",true);for(String k:List.of("knowledge_base_id","language"))if(payload.hasNonNull(k)&&!payload.path(k).isTextual())throw new TaskFailure("unmarshal knowledge base profile payload",true);if(payload.hasNonNull("tenant_id")&&(!payload.path("tenant_id").isIntegralNumber()||!payload.path("tenant_id").canConvertToLong()||payload.path("tenant_id").asLong()<0))throw new TaskFailure("unmarshal knowledge base profile payload",true);if(payload.hasNonNull("force")&&!payload.path("force").isBoolean())throw new TaskFailure("unmarshal knowledge base profile payload",true);var output=json.createObjectNode();if(job.tenantId()<=0||payload.path("tenant_id").asLong()!=job.tenantId())return output.put("skipped","knowledge_base_not_found");cancellation.check();var loaded=repository.base(job.tenantId(),payload.path("knowledge_base_id").asText());if(loaded.isEmpty())return output.put("skipped","knowledge_base_not_found");var base=loaded.get();boolean force=payload.path("force").asBoolean();if(!force&&!base.path("profile_config").path("enabled").asBoolean())return output.put("skipped","automatic_generation_disabled");if(!eligible(base))return output.put("skipped","unsupported_knowledge_base");var watcher=Executors.newSingleThreadScheduledExecutor(r->{var t=new Thread(r,"native-kb-profile-cancellation");t.setDaemon(true);return t;});try(var call=CallContext.timeout(timeout())){var monitor=watcher.scheduleWithFixedDelay(()->{if(cancellation.isCanceled())call.cancel();},25,25,TimeUnit.MILLISECONDS);try{var result=new KnowledgeBaseProfileGenerator(repository,json,models,text,clock).generate(job.tenantId(),base,force,payload.path("language").asText(),call,cancellation::check,profile->repository.save(job,profile));if(result.cached())return output.put("skipped","aggregate_unchanged");output.put("status",result.profile().path("status").asText());if(result.profile().has("model_id"))output.set("model_id",result.profile().get("model_id"));return output;}catch(KnowledgeBaseProfileGenerator.ModelMissing e){return output.put("status","failed").put("skipped","model_not_configured");}catch(CancellationException e){throw e;}catch(RuntimeException e){throw new TaskFailure("knowledge base profile generation failed",true);}finally{monitor.cancel(false);}}finally{watcher.shutdownNow();}}
}